script:
class DialogManager {
  static INPUT_STYLE =
    "font-size: 14px; width: 100%; padding: 6px 8px; line-height: 1.15; " +
    "border: 1px solid var(--ink-gray-1); border-radius: .5rem; " +
    "background-color: #F3F3F3; color: var(--ink-gray-8);";

  static LABEL_STYLE =
    "display: block; font-size: 13px; font-weight: 450; margin-bottom: 0.25rem; color: var(--ink-gray-6); line-height: 1.5; letter-spacing: 0.02em;";

  static _esc(str) {
    if (str == null) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  static _renderInput(field) {
    const e = DialogManager._esc;
    const s = DialogManager.INPUT_STYLE;
    const req = field.required ? " required" : "";

    if (field.type === "textarea") {
      return `<textarea class="form-input" id="${e(field.id)}" rows="${field.rows || 3}" style="${s} resize: vertical;"${req}>${e(field.value || "")}</textarea>`;
    }

    if (field.type === "select") {
      const opts = (field.options || [])
        .map((opt) => {
          const val = typeof opt === "string" ? opt : opt.value;
          const lbl = typeof opt === "string" ? opt : opt.label;
          return `<option value="${e(val)}"${field.value === val ? " selected" : ""}>${e(lbl)}</option>`;
        })
        .join("");
      return `<select class="form-input" id="${e(field.id)}" style="${s}"${req}><option value=""></option>${opts}</select>`;
    }

    const placeholder = field.placeholder
      ? ` placeholder="${e(field.placeholder)}"`
      : "";
    return `<input class="form-input" type="${e(field.type || "text")}" id="${e(field.id)}" style="${s}" value="${e(field.value || "")}"${placeholder}${req}>`;
  }

  static renderField(field) {
    const e = DialogManager._esc;

    if (field.type === "row") {
      const idAttr = field.id ? ` id="${e(field.id)}"` : "";
      const hiddenStyle = field.hidden ? ' style="display: none;"' : "";
      return `<div${idAttr} class="form-row"${hiddenStyle}>${field.fields.map(DialogManager.renderField).join("")}</div>`;
    }

    if (field.type === "checkbox") {
      return `
        <div class="form-group" style="display: flex; align-items: center; gap: 0.5rem;">
          <input type="checkbox" id="${e(field.id)}" style="accent-color: var(--ink-gray-9);"${field.value ? " checked" : ""}>
          <label for="${e(field.id)}" style="font-size: 13px; color: var(--ink-gray-7); margin: 0;">${e(field.label)}</label>
        </div>`;
    }

    const wrapStyle = field.flex ? ` style="flex: ${field.flex};"` : "";
    const requiredMark = field.required
      ? ` <span style="color: var(--red-5, #e53e3e);">*</span>`
      : "";

    return `
      <div class="form-group"${wrapStyle}>
        <label for="${e(field.id)}" style="${DialogManager.LABEL_STYLE}">${e(field.label)}${requiredMark}</label>
        ${DialogManager._renderInput(field)}
      </div>`;
  }

  static collectValues(fields, out = {}) {
    fields.forEach((field) => {
      if (field.type === "row") {
        DialogManager.collectValues(field.fields, out);
        return;
      }
      const el = document.getElementById(field.id);
      if (!el) return;
      out[field.id] = field.type === "checkbox" ? el.checked : el.value;
    });
    return out;
  }

  static wireListeners(fields) {
    fields.forEach((field) => {
      if (field.type === "row") {
        DialogManager.wireListeners(field.fields);
        return;
      }
      if (field.type === "checkbox" && field.toggles) {
        const checkbox = document.getElementById(field.id);
        const target = document.getElementById(field.toggles);
        if (!checkbox || !target) return;
        target.style.display = checkbox.checked ? "none" : "flex";
        checkbox.addEventListener("change", (e) => {
          target.style.display = e.target.checked ? "none" : "flex";
        });
      }
    });
  }

  constructor() {
    this.dialogs = [];

    this.show = this.show.bind(this);
    this.remove = this.remove.bind(this);
    this.handleEsc = this.handleEsc.bind(this);
  }

  show(options) {
    const config = {
      title: options.title || "",
      message: options.message || "",
      html: options.html || "",
      error: options.error || "",
      size: options.size || "md", // sm, md, lg, xl, 2xl
      actions: options.actions || [],
      onClose: options.onClose || null,
    };

    // Create Backdrop
    const backdrop = document.createElement("div");
    backdrop.className = "frappe-dialog-backdrop";
    backdrop.setAttribute("role", "dialog");
    backdrop.setAttribute("aria-modal", "true");

    // Create Panel
    const panel = document.createElement("div");
    panel.className = `frappe-dialog-panel fd-size-${config.size}`;

    // Prevent click inside panel from bubbling to backdrop
    panel.addEventListener("click", (e) => e.stopPropagation());

    // Header
    const header = document.createElement("div");
    header.className = "frappe-dialog-header";
    header.innerHTML = `
            <h3 class="frappe-dialog-title">${config.title}</h3>
            <button class="frappe-dialog-close" aria-label="Close">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                    <line x1="18" y1="6" x2="6" y2="18"></line>
                    <line x1="6" y1="6" x2="18" y2="18"></line>
                </svg>
            </button>
        `;

    // Body
    const body = document.createElement("div");
    body.className = "frappe-dialog-body";

    if (config.message) {
      const p = document.createElement("p");
      p.textContent = config.message;
      body.appendChild(p);
    }

    if (config.html) {
      const div = document.createElement("div");
      div.innerHTML = config.html;
      body.appendChild(div);
    }

    if (config.error) {
      const err = document.createElement("div");
      err.className = "frappe-dialog-error";
      err.textContent = config.error;
      body.appendChild(err);
    }

    // Assembly (Partial)
    panel.appendChild(header);
    panel.appendChild(body);

    // Footer / Actions
    if (config.actions && config.actions.length > 0) {
      const footer = document.createElement("div");
      footer.className = "frappe-dialog-footer";

      config.actions.forEach((action) => {
        const btn = document.createElement("button");
        btn.textContent = action.label;

        // Map Frappe UI button props to classes
        let btnClass = "frappe-btn ";
        if (action.theme === "red") {
          btnClass +=
            action.variant === "solid"
              ? "frappe-btn-red-solid"
              : "frappe-btn-default text-red-600";
        } else {
          btnClass +=
            action.variant === "solid"
              ? "frappe-btn-solid"
              : "frappe-btn-default";
        }
        btn.className = btnClass;

        btn.addEventListener("click", () => {
          if (typeof action.onClick === "function") {
            // Pass the specific close function for this instance
            action.onClick(() => this.remove(backdrop, config.onClose));
          } else {
            this.remove(backdrop, config.onClose);
          }
        });
        footer.appendChild(btn);
      });
      panel.appendChild(footer);
    }

    backdrop.appendChild(panel);
    document.body.appendChild(backdrop);

    // Event Listeners for Closing
    const closeBtn = header.querySelector(".frappe-dialog-close");
    closeBtn.addEventListener("click", () =>
      this.remove(backdrop, config.onClose),
    );
    backdrop.addEventListener("click", () =>
      this.remove(backdrop, config.onClose),
    );

    // Manage state
    this.dialogs.push(backdrop);

    if (this.dialogs.length === 1) {
      document.body.classList.add("frappe-dialog-open");
      document.addEventListener("keydown", this.handleEsc);
    }

    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        backdrop.classList.add("fd-show");
      });
    });

    return {
      close: () => this.remove(backdrop, config.onClose),
    };
  }

  remove(backdrop, onCloseCallback) {
    if (!backdrop || !document.body.contains(backdrop)) return;

    backdrop.classList.remove("fd-show");

    setTimeout(() => {
      if (document.body.contains(backdrop)) {
        backdrop.remove();
      }

      this.dialogs = this.dialogs.filter((d) => d !== backdrop);

      if (this.dialogs.length === 0) {
        document.body.classList.remove("frappe-dialog-open");
        document.removeEventListener("keydown", this.handleEsc);
      }

      if (typeof onCloseCallback === "function") {
        onCloseCallback();
      }
    }, 200);
  }

  handleEsc(e) {
    if (e.key === "Escape" && this.dialogs.length > 0) {
      const topDialog = this.dialogs[this.dialogs.length - 1];
      this.remove(topDialog);
    }
  }

  renderFormDialog({
    title,
    size = "md",
    fields = [],
    saveLabel = "Save",
    onSave,
    onClose,
  }) {
    const bodyHtml = `<div style="display: flex; flex-direction: column; gap: 1rem;">${fields.map(DialogManager.renderField).join("")}</div>`;

    const dialogRef = this.show({
      title,
      size,
      html: bodyHtml,
      onClose,
      actions: [
        {
          label: saveLabel,
          variant: "solid",
          onClick: async (close) => {
            const values = DialogManager.collectValues(fields);
            await onSave(values, close);
          },
        },
        {
          label: "Cancel",
          onClick: (close) => {
            if (typeof onClose === "function") onClose();
            close();
          },
        },
      ],
    });

    const backdrop = this.dialogs[this.dialogs.length - 1];

    setTimeout(() => {
      DialogManager.wireListeners(fields);

      if (backdrop) {
        backdrop.addEventListener("keydown", async (e) => {
          if (
            e.key === "Enter" &&
            document.activeElement?.tagName !== "TEXTAREA"
          ) {
            e.preventDefault();
            const values = DialogManager.collectValues(fields);
            await onSave(values, dialogRef.close);
          }
        });
      }
    }, 50);
  }
}

window.dialogManager = new DialogManager();

window.dialog = function (options) {
  return window.dialogManager.show(options);
};

window.renderFormDialog = function (options) {
  return window.dialogManager.renderFormDialog(options);
};
